mapper.sql:


WHERE s.company_id = #{companyId} AND s.location_id = 0
AND s.qty <> 0
AND s.warehouse_id = #{q.warehouseId}
AND k.style_id = #{q.styleId}



            AND (upper(k.code) IN #{c}
                 OR upper(st.code) IN #{c})

        AND (upper(k.code) LIKE #{kw} OR upper(st.code) LIKE #{kw} OR st.name ILIKE #{nameKw})

mapper.select:
SELECT s.id, s.company_id, s.warehouse_id, w.name AS warehouse_name, s.style_sku_id, s.qty, s.update_time FROM fg_stock s JOIN bas_warehouse w ON w.id = s.warehouse_id JOIN sty_style_sku k ON k.id = s.style_sku_id JOIN sty_style st ON st.id = k.style_id
AND s.id IN #{id}
ORDER BY w.name, k.code, s.id
